-- title: Appointment no-show summary by month
-- question: How many scheduled appointments were fulfilled, missed or cancelled in each of the last complete months?
-- key: month
-- requires: appointments
-- param months: 12
-- limitations: Synthea has no scheduling data, so the appointments table is a synthetic extension generated by this kit. The no-show rate is no-shows / all scheduled (cancelled included in the denominator). Covers the last N complete calendar months (N = the months parameter) before the report date's month, so no month is partial. Synthetic data.
SELECT substr(date, 1, 7) AS month,
       COUNT(*) AS scheduled,
       SUM(status = 'fulfilled') AS fulfilled,
       SUM(status = 'noshow') AS noshow,
       SUM(status = 'cancelled') AS cancelled,
       ROUND(100.0 * SUM(status = 'noshow') / COUNT(*), 1) AS noshow_rate_pct
FROM appointments
WHERE date < date(:as_of, 'start of month')
  AND date >= date(:as_of, 'start of month', '-' || :months || ' months')
GROUP BY substr(date, 1, 7)
ORDER BY month;
